// Molitvoslov (m-tropari-velikomuchenikam-svyashhennomuchenikam-prepodobnomuchenikam-muchenikam): Church Slavonic text. Source: azbyka.ru, "Тропари великомученикам, священномученикам, преподобномученикам, мученикам" (https://azbyka.ru/molitvoslov/tropari-velikomuchenikam-svyashhennomuchenikam-prepodobnomuchenikam-muchenikam.html).
//   Used with the written permission of azbyka.ru; remove on request. Generated from the page by a
//   script (markup removed, nothing else changed). Generated 2026-11-21.
import type { LiturgyBlock } from '../types';

export const blocks: readonly LiturgyBlock[] = [
  {"id": "cu-mol-0001", "section": "service", "who": "rubric", "text": "Тропари великомученикам"},
  {"id": "cu-mol-0002", "section": "service", "who": "rubric", "text": "Анастасии Узорешительнице,"},
  {"id": "cu-mol-0003", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0004", "section": "service", "who": "reader", "text": "Победоноснаго Воскресения/ истинноименитая наречена еси, мученице Христова,/ победы на враги поставила еси мук терпением,/ Христа ради, Жениха твоего,/ Егоже возлюбила еси./ Того моли// спасти души наша."},
  {"id": "cu-mol-0005", "section": "service", "who": "rubric", "text": "Кондак,"},
  {"id": "cu-mol-0006", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "cu-mol-0007", "section": "service", "who": "reader", "text": "Во искушениих и скорбех сущии,/ к твоему храму притекающе,/ приемлют честная дарования/ от живущия в тебе Божественныя благодати, Анастасие:// ты бо присно миру точиши исцеления."},
  {"id": "cu-mol-0008", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0009", "section": "service", "who": "rubric", "text": "Артемию Антиохийскому,"},
  {"id": "cu-mol-0010", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0011", "section": "service", "who": "reader", "text": "Истинною бо Христовою верою/ утверждься, страстотерпче,/ мучителя злочестива царя/ победил еси со идольским того возношением./ Тем от Царя Великаго, вечно царствующаго,/ пресветлым венцем победным одарен бысть,/ вся исцеляяй болящия и призывающия тя, Артемие великий,/ моли Христа Бога// спасти души наша."},
  {"id": "cu-mol-0012", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0013", "section": "service", "who": "rubric", "text": "Варваре Илиопольской,"},
  {"id": "cu-mol-0014", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0015", "section": "service", "who": "reader", "text": "Агнице всеблаженная Варваро,/ Божественне озарившися Светом Святыя Троицы Трисолнечным/ и в купели Крещения утвердившися,/ в побеждение лести отеческия,/ веру исповедала еси Христову./ Темже, всечестная, свыше благодать тебе дарова Бог,/ исцеляти недуги и болезни вся.// Егоже моли, великомученице, да спасет души наша."},
  {"id": "cu-mol-0016", "section": "service", "who": "rubric", "text": "Ин тропарь, глас 8"},
  {"id": "cu-mol-0017", "section": "service", "who": "reader", "text": "Варвару святую почтим:/ вражия бо сети сокруши/ и яко птица избавися от них,// помощию и оружием Креста, всечестная."},
  {"id": "cu-mol-0018", "section": "service", "who": "rubric", "text": "Кондак, глас 4"},
  {"id": "cu-mol-0019", "section": "service", "who": "reader", "text": "В Троице благочестно певаемому/ последовавши Богу, страстотерпице,/ идольская притупила еси чтилища,/ посреде же подвига страдальчествующи, Варваро,/ мучителей прещения не устрашилася еси, мужемудренная,/ велегласно поющи присно:// Троицу чту, едино Божество."},
  {"id": "cu-mol-0020", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0021", "section": "service", "who": "rubric", "text": "Георгию Победоносцу,"},
  {"id": "cu-mol-0022", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0023", "section": "service", "who": "reader", "text": "Яко пленных свободитель/ и нищих защититель,/ немощствующих врач,/ православных поборниче,/ победоносче великомучениче Георгие,// моли Христа Бога спастися душам нашим."},
  {"id": "cu-mol-0024", "section": "service", "who": "rubric", "text": "Ин тропарь, глас тойже"},
  {"id": "cu-mol-0025", "section": "service", "who": "reader", "text": "Подвигом добрым подвизался еси, страстотерпче Христов,/ верою, и мучителей обличил еси нечестие,/ жертва же благоприятна Богу принеслся еси,/ темже и венец приял еси победы,// и молитвами, святе, твоими всем подаеши прегрешений прощение."},
  {"id": "cu-mol-0026", "section": "service", "who": "rubric", "text": "Ин тропарь, на освящение церкви вмч. Георгия в Киеве,"},
  {"id": "cu-mol-0027", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0028", "section": "service", "who": "reader", "text": "Днесь блажат тя мира концы,/ Божественных чудес исполншеся,/ и земля радуется, напившися крове твоея./ Христоименитии же людие града Киева/ освящением Божественнаго храма твоего радостию возвеселишася,/ страстотерпче Георгие,/ сосуде избранный Святаго Духа, угодниче Христов./ Егоже моли/ с верою и мольбою приходящим во святый твой храм/ дати очищение грехов,// умирити мир и спасти души наша."},
  {"id": "cu-mol-0029", "section": "service", "who": "rubric", "text": "Кондак, глас 8"},
  {"id": "cu-mol-0030", "section": "service", "who": "reader", "text": "К возбранному и скорому заступлению твоему прибегше вернии,/ молим избавитися, страстотерпче Христов, от соблазн вражиих,/ воспевающим тя, и всяких бед и озлоблений, да зовем:// радуйся, мучениче Георгие."},
  {"id": "cu-mol-0031", "section": "service", "who": "rubric", "text": "Ин кондак, глас 4"},
  {"id": "cu-mol-0032", "section": "service", "who": "reader", "text": "Возделан от Бога показался еси благочестия делатель честнейший,/ добродетелей рукояти собрав себе,/ сеяв бо в слезах, веселием жнеши,/ страдальчествовав же кровию, Христа приял еси,// и молитвами, святе, твоими всем подаеши прегрешений прощение."},
  {"id": "cu-mol-0033", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0034", "section": "service", "who": "rubric", "text": "Димитрию Солунскому,"},
  {"id": "cu-mol-0035", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0036", "section": "service", "who": "reader", "text": "Велика обрете в бедах/ тя поборника вселенная, страстотерпче,/ языки побеждающа./ Якоже убо Лиеву низложил еси гордыню,/ и на подвиг дерзновенна сотворив Нестора,/ тако, святе Димитрие,/ Христу Богу молися// даровати нам велию милость."},
  {"id": "cu-mol-0037", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0038", "section": "service", "who": "rubric", "text": "Евфимии Всехвальной,"},
  {"id": "cu-mol-0039", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0040", "section": "service", "who": "reader", "text": "Жениха твоего Христа возлюбивши,/ и свещу твою светло уготовльши,/ добродетельми возсиявши, всехвальная Евфимие,/ тем возшла еси с Ним на брак,/ венец страдания от Него приемши./ Но от бед избави нас,// чтущих верою память твою."},
  {"id": "cu-mol-0041", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0042", "section": "service", "who": "rubric", "text": "Екатерине Александрийской,"},
  {"id": "cu-mol-0043", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0044", "section": "service", "who": "reader", "text": "Добродетельми, яко лучами солнечными,/ просветила еси неверныя мудрецы./ И, якоже пресветлая луна ходящим в нощи/ неверия тьму отгнала еси,/ и царицу уверила еси,/ вкупе же и мучителя обличила еси,/ Богозванная невесто блаженная Екатерино,/ желанием востекла еси в Небесный чертог/ к прекрасному Жениху Христу,/ и от Него царским венцем венчалася еси:/ Емуже, со Ангелы предстоящи,/ за ны молися,// творящия пречестную память твою."},
  {"id": "cu-mol-0045", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0046", "section": "service", "who": "rubric", "text": "Иакову Персянину,"},
  {"id": "cu-mol-0047", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0048", "section": "service", "who": "reader", "text": "Мучении странноужасными и доблестию терпения/ всех преудивил еси, многострадальне,/ над коимждо составом удеси резания,/ благодарны мольбы предивне изрекл еси Господу./ Тем, во страдании твоем венец прием,/ к Престолу возшел еси Небеснаго Царя Христа Бога, Иакове,// Того моли спасти души наша."},
  {"id": "cu-mol-0049", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0050", "section": "service", "who": "rubric", "text": "Иоанну Новому, Сочавскому,"},
  {"id": "cu-mol-0051", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0052", "section": "service", "who": "reader", "text": "Житие на земли добре окормляя, страдальче,/ милостынями, и частыми молитвами, и слезами,/ паки же ко страданию мужески устремився,/ персское обличил еси нечестие./ Темже Церкве был еси утверждение/ и христиан похвало,// Иоанне приснопамятне."},
  {"id": "cu-mol-0053", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0054", "section": "service", "who": "rubric", "text": "Мине Котуанскому,"},
  {"id": "cu-mol-0055", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0056", "section": "service", "who": "reader", "text": "Яко Безплотным собеседника/ и страстотерпцем единовсельника,/ сошедшеся верою, Мино, восхваляем тя,/ мира мирови испроси// и душам нашим велия милости."},
  {"id": "cu-mol-0057", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0058", "section": "service", "who": "rubric", "text": "Никите Готфскому,"},
  {"id": "cu-mol-0059", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0060", "section": "service", "who": "reader", "text": "Крест Христов, яко некое оружие усердно восприим,/ и к борению врагов притекл еси,/ и за Христа пострадав,/ последи огнем священную твою душу Господу предал еси:/ отонудуже и даров исцеления/ от Него сподобился еси прияти,/ великомучениче Никито./ Моли Христа Бога// спастися душам нашим."},
  {"id": "cu-mol-0061", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0062", "section": "service", "who": "rubric", "text": "Николаю Софийскому,"},
  {"id": "cu-mol-0063", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0064", "section": "service", "who": "reader", "text": "Зарею Духа обогатився, славне,/ и оттуду восприим дерзновение,/ исповедал еси на судищи мужески Троицу Единосущную,/ темже и камением побиваемь,/ не покорился еси./ Огнем же сожигаемь,/ обличил еси прелесть безбожных,/ многострадальне святе Николае./ Сего ради молим тя:/ испроси душам нашим// велию милость."},
  {"id": "cu-mol-0065", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0066", "section": "service", "who": "rubric", "text": "Пантелеимону целителю,"},
  {"id": "cu-mol-0067", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0068", "section": "service", "who": "reader", "text": "Страстотерпче святый и целебниче Пантелеимоне,/ моли Милостиваго Бога,/ да прегрешений оставление// подаст душам нашим."},
  {"id": "cu-mol-0069", "section": "service", "who": "rubric", "text": "Величание"},
  {"id": "cu-mol-0070", "section": "service", "who": "reader", "text": "Величаем тя,/ страстотерпче святый, великомучениче и целебниче Пантелеимоне,/ и чтим честная страдания твоя,/ яже за Христа// претерпел еси."},
  {"id": "cu-mol-0071", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0072", "section": "service", "who": "rubric", "text": "Феодору Стратилату,"},
  {"id": "cu-mol-0073", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0074", "section": "service", "who": "reader", "text": "Воинствословием истинным, страстотерпче,/ Небеснаго Царя воевода предобрый был еси, Феодоре:/ оружиями бо веры ополчился еси мудренно/ и победил еси демонов полки,/ и победоносный явился еси страдалец./ Темже тя верою// присно ублажаем."},
  {"id": "cu-mol-0075", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0076", "section": "service", "who": "rubric", "text": "Феодору Тирону,"},
  {"id": "cu-mol-0077", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "cu-mol-0078", "section": "service", "who": "reader", "text": "Велия веры исправления,/ во источнице пламене, яко на воде упокоения,/ святый мученик Феодор радовашеся;/ огнем бо всесожжегся,/ яко хлеб сладкий Троице принесеся./ Того молитвами, Христе Боже,// спаси души наша."},
  {"id": "cu-mol-0079", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0080", "section": "service", "who": "rubric", "text": "^ Тропари священномученикам"},
  {"id": "cu-mol-0081", "section": "service", "who": "rubric", "text": "Александру (Хотовицкому), протопресвитеру,"},
  {"id": "cu-mol-0082", "section": "service", "who": "rubric", "text": "глас 6"},
  {"id": "cu-mol-0083", "section": "service", "who": "reader", "text": "Кротость и смирение стяжавый,/ любовь Христову пастве своей показал еси/ в годину огненных искушений Церкве Российския/ и, яко пастырь добрый,/ душу свою за ню положил еси./ Молися о нас, священномучениче Александре,// просветити души наша."},
  {"id": "cu-mol-0084", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0085", "section": "service", "who": "rubric", "text": "Антипе, еп. Пергама Асийского,"},
  {"id": "cu-mol-0086", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0087", "section": "service", "who": "reader", "text": "Идольския лести упразднил еси, Антипо,/ и, диавольскую поправ силу,/ пред богоборцы дерзновенно Христа исповедал еси./ Темже со Ангельскими чины в Вышних водворяяся,/ Владыце всех славословие принося,/ и о нас молебное благодарение предлагаеши,/ благодать цельбы даруя./ Сего ради тя чтим,/ священномучениче Антипо,/ моли Христа Бога,// да спасет души наша."},
  {"id": "cu-mol-0088", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0089", "section": "service", "who": "rubric", "text": "Афиногену, еп., и десяти ученикам его,"},
  {"id": "cu-mol-0090", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0091", "section": "service", "who": "reader", "text": "Священный Богу Афиноген, в жертве служитель,/ священное ученик своих принесе Христу заколение,/ пастырь со словесными овцами иде в Небесную ограду,/ победив сверепеющия неверием языки./ Мученик Твоих молитвами, Христе Боже,// спаси стадо Твое от волков, губящих е."},
  {"id": "cu-mol-0092", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0093", "section": "service", "who": "rubric", "text": "Вениамину, митр. Петроградскому и Гдовскому,"},
  {"id": "cu-mol-0094", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0095", "section": "service", "who": "reader", "text": "Светильник всесветлый во граде святаго Петра явился еси,/ пастырю добрый, священномучениче отче Вениамине./ Любовь и милосердие в сердцах верных насаждая,/ благотворити призывал еси терпящим глад и нищету./ Сего ради и мы к тебе прибегаем и с верою вопием ти:/ моли милостиваго Бога,/ отечество наше в Православии и благочестии утвердити,/ мир Церкви даровати// и душам нашим велию милость."},
  {"id": "cu-mol-0096", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0097", "section": "service", "who": "rubric", "text": "Владимиру, митр. Киевскому и Галицкому,"},
  {"id": "cu-mol-0098", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "cu-mol-0099", "section": "service", "who": "reader", "text": "Веры Православныя непорочный блюстителю/ и заповедей Христовых усердный исполнителю,/ священномучениче Владимире,/ Христа всем сердцем возлюбив,/ паству твою добре упасл еси,/ незлобиво мученическую смерть приял еси./ Сего ради в вечной славе пребывая,// моли спастися душам нашим."},
  {"id": "cu-mol-0100", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0101", "section": "service", "who": "rubric", "text": "Григорию V, патриарху Константинопольскому,"},
  {"id": "cu-mol-0102", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0103", "section": "service", "who": "reader", "text": "Благословен еси, Христе Боже наш,/ укрепивый Божественнаго патриарха,/ низпославый тому свыше Свою благодать,/ имже и нас свободил еси от работы вражия,// Человеколюбче, слава Тебе."},
  {"id": "cu-mol-0104", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0105", "section": "service", "who": "rubric", "text": "Дионисию Ареопагиту, еп. Афинскому,"},
  {"id": "cu-mol-0106", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0107", "section": "service", "who": "reader", "text": "Благости научився, и трезвяся во всех,/ благою совестию священнолепно оболкся,/ почерпл еси от сосуда избраннаго неизреченная,/ и веру соблюд, равное течение совершил еси,/ священномучениче Дионисие,// моли Христа Бога, спастися душам нашим."},
  {"id": "cu-mol-0108", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0109", "section": "service", "who": "rubric", "text": "Дорофею, еп. Тирскому,"},
  {"id": "cu-mol-0110", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "cu-mol-0111", "section": "service", "who": "reader", "text": "Нищелюбием обогатився/ и милость воздержания источив,/ наслаждения Царствия Небеснаго сподобися,/ страдальчески беды приим по стаде своем,/ и апостолом обретеся ссельник,/ отче священномучениче Дорофее,/ моли Христа Бога// спастися душам нашим."},
  {"id": "cu-mol-0112", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0113", "section": "service", "who": "rubric", "text": "Еразму Охридскому,"},
  {"id": "cu-mol-0114", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0115", "section": "service", "who": "reader", "text": "Преподобно житие твое прошед, мудре,/ светлым украсился еси хитоном священства./ Проливая же кровь мученичества, Еразме,/ сподобился еси свыше мздов нелестных/ и, предстоя Троице, молишися о нас, воспевающих тя."},
  {"id": "cu-mol-0116", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0117", "section": "service", "who": "rubric", "text": "Ермогену, патриарху Московскому и всея Руси, чдтв.,"},
  {"id": "cu-mol-0118", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0119", "section": "service", "who": "reader", "text": "Российския земли первопрестольниче/ и неусыпный о ней к Богу молитвенниче!/ За веру Христову и паству твою душу свою положив,/ страну нашу от нечестия избавил еси./ Темже вопием ти:/ спасай нас молитвами твоими,// священномучениче Ермогене, отче наш."},
  {"id": "cu-mol-0120", "section": "service", "who": "rubric", "text": "Ин тропарь, на прославление,"},
  {"id": "cu-mol-0121", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0122", "section": "service", "who": "reader", "text": "Приспе день светлаго торжества,/ град Москва радуется,/ и с ним Русь Православная ликовствует/ песньми и пеньми духовными:/ днесь бо священное торжество/ в явлении честных и многоцелебных мощей/ святителя и чудотворца Ермогена,/ якоже солнце незаходимое возсия светозарными лучами,/ разгоняя тьму искушений же и бед/ от вопиющих верно:// спасай нас, яко предстатель наш, великий Ермогене."},
  {"id": "cu-mol-0123", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0124", "section": "service", "who": "rubric", "text": "Ермолаю, иерею Никомидийскому,"},
  {"id": "cu-mol-0125", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0126", "section": "service", "who": "reader", "text": "Миром благодати помазан,/ преблаженне отче Ермолае,/ иерей Бога Вышняго явился еси/ и благочестия светлый проповедник,/ мученик же твердый и безмездный врач притекающих к тебе./ Слава Давшему тебе крепость,/ слава Венчавшему тя,// слава Действующему тобою всем исцеления."},
  {"id": "cu-mol-0127", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0128", "section": "service", "who": "rubric", "text": "Ермолаю, Ермиппу и Ермократу, иереям Никомидийским,"},
  {"id": "cu-mol-0129", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0130", "section": "service", "who": "reader", "text": "Троицы провозвестницы,/ троице мучеников честная,/ идольское нечестие обличившии/ и тьмочисленнаго врага сокрушившии,/ ныне, со Христом царствующе, молите,/ священный Ермолае со Ермиппом и Ермократом славным,/ яко да и наша враги победим/ и приимем от Царя всех, Бога, вечный живот// и венец нетленный."},
  {"id": "cu-mol-0131", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0132", "section": "service", "who": "rubric", "text": "Игнатию Богоносцу,"},
  {"id": "cu-mol-0133", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0134", "section": "service", "who": "reader", "text": "Апостольских нравов подражателю/ и престола их сонаследниче,/ архиереев удобрение и мучеников славо, Богодухновенне,/ на огнь, и меч, и звери дерзнул еси, веры ради/ и, слово истины исправляя,/ до крове пострадал еси,/ священномучениче Игнатие,/ моли Христа Бога// спастися душам нашим."},
  {"id": "cu-mol-0135", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0136", "section": "service", "who": "rubric", "text": "Иерофею, еп. Афинскому,"},
  {"id": "cu-mol-0137", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0138", "section": "service", "who": "reader", "text": "Благости научився и трезвяся во всех/ благою совестию священнолепно оболкся,/ почерпл еси от сосуда избраннаго неизреченная/ и, веру соблюд, равное течение совершил еси,/ священномучениче Иерофее.// Моли Христа Бога спастися душам нашим."},
  {"id": "cu-mol-0139", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0140", "section": "service", "who": "rubric", "text": "Иоанну Петроградскому, протоиерею,"},
  {"id": "cu-mol-0141", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0142", "section": "service", "who": "reader", "text": "Любовию к Богу распаляемь,/ жизнь свою мученически за Христа и ближних положил еси,/ сего ради венец правды от Него приял еси./ Моли Всеблагаго Бога, священномучениче Иоанне, Церковь Святую сохранити в мире// и спасти души наша."},
  {"id": "cu-mol-0143", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0144", "section": "service", "who": "rubric", "text": "Иосифу Астраханскому, митр.,"},
  {"id": "cu-mol-0145", "section": "service", "who": "rubric", "text": "глас 6"},
  {"id": "cu-mol-0146", "section": "service", "who": "reader", "text": "Подвигом добрым подвизався,/ жизнь твою страданиями за правду увенчав,/ преселился еси в Небесныя обители,/ идеже предстоя Престолу Святыя Троицы,/ моли, святителю Иосифе,// граду Астрахани и отечеству нашему в мире спастися."},
  {"id": "cu-mol-0147", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0148", "section": "service", "who": "rubric", "text": "Ипатию, еп. Гангрскому,"},
  {"id": "cu-mol-0149", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0150", "section": "service", "who": "reader", "text": "Изволением Божественнаго разума/ вперив ум свой в Небесныя обители/ и равно Ангелом житие пожив на земли,/ сего ради мучения красоты венец на своем версе утвердив,/ священномучениче Ипатие,/ моли Христа Бога// спастися душам нашим."},
  {"id": "cu-mol-0151", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0152", "section": "service", "who": "rubric", "text": "Иринею Сремскому,"},
  {"id": "cu-mol-0153", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0154", "section": "service", "who": "reader", "text": "Жизнь твою целомудренно совершил еси, ничтоже на земли паче Христа предпочет, радуяся, вшел еси на мученическое благославие, противяся мучителя повелению, явился еси венценосец священный, ибо Христос возмездие тебе дарова и всели тя в Царство Небесное."},
  {"id": "cu-mol-0155", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0156", "section": "service", "who": "rubric", "text": "Исидору, пресвитеру, и иже с ним 72-м в Юрьеве Лифляндском пострадавшим,"},
  {"id": "cu-mol-0157", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "cu-mol-0158", "section": "service", "who": "reader", "text": "Страстотерпцы Господни блаженнии,/ Православную веру Христову со дерзновением проповедасте,/ и на судищи учения врагов неправая обличисте,/ того ради и ввержени бысте, святии,/ во глубину речную,/ души же ваши вселишася в Небесныя кровы,/ идеже со святыми предстояще Престолу Царя всех Бога,/ молитеся Ему за вся православныя люди,// подвиги ваша честно почитающия."},
  {"id": "cu-mol-0159", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0160", "section": "service", "who": "rubric", "text": "Кириллу, еп. Гортинскому,"},
  {"id": "cu-mol-0161", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0162", "section": "service", "who": "reader", "text": "Гласом божественным от темницы изведен,/ в Риме братию в божественней вере утвердил еси,/ и, от Ангела глаголы приим о святительстей пастве,/ во страдании своем паки гласу с Небесе сподобися,/ богоповеленный святителю и страдальче Кирилле,// моли за души наша."},
  {"id": "cu-mol-0163", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0164", "section": "service", "who": "rubric", "text": "Клименту, еп. Анкирскому,"},
  {"id": "cu-mol-0165", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0166", "section": "service", "who": "reader", "text": "Лоза преподобства и стебль страдальчества,/ цвет священнейший и плод Богоданный,/ верным, всесвященне, присноцветущ, даровался еси,/ но яко мучеников сострадалец/ и священноначальников сопрестольник,/ моли Христа Бога// спастися душам нашим."},
  {"id": "cu-mol-0167", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0168", "section": "service", "who": "rubric", "text": "Клименту, папе Римскому,"},
  {"id": "cu-mol-0169", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0170", "section": "service", "who": "reader", "text": "Иже от Бога чудодействы/ преславно удивляя вселенныя концы мира,/ священный страдальче,/ паче естества морю, составы водам содеваеши разделение/ в честней памяти твоей/ всегда притекающим усердно в Богозданную ти церковь,/ чудесным твоим мощем,/ и по всенародном хождении/ море во едино течение чудодетельне твориши,/ Клименте предивный,// моли Христа Бога, спастися душам нашим."},
  {"id": "cu-mol-0171", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0172", "section": "service", "who": "rubric", "text": "Константину Голубеву, протоиерею,"},
  {"id": "cu-mol-0173", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0174", "section": "service", "who": "reader", "text": "Украшение священников явился еси Константине, восприем бо крест яко оружие,/ проповедию славною устраняя раскол и ереси,/ благовествовал еси Иисуса Христа глаголя:/ спасайтеся от рода сего развращеннаго./ Сего ради мученическою кровию обагрися славне,/ и ныне радуяся с лики ангельскими,/ моли Христа Бога Церковь Всероссийскую/ от ересей и расколов сохранити/ и спасти души наша."},
  {"id": "cu-mol-0175", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0176", "section": "service", "who": "rubric", "text": "Лукиану, пресвитеру Антиохийскому,"},
  {"id": "cu-mol-0177", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0178", "section": "service", "who": "reader", "text": "Воздержанием постничества и мучения кровию/ ты, стяжав венец неувядаемый, священномучениче Лукиане,/ Антиохийская похвало,/ о нас моли Христа Бога,// творящих святую память твою."},
  {"id": "cu-mol-0179", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0180", "section": "service", "who": "rubric", "text": "Лукиану Печерскому, в Дальних пещерах,"},
  {"id": "cu-mol-0181", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0182", "section": "service", "who": "reader", "text": "И нравом причастник, и престолом наместник апостолом быв,/ деяние обрел еси, Богодухновенне, в видения восход./ Сего ради, Слово Истины исправляя,/ и веры ради пострадал еси даже до крове,/ священномучениче Лукиане,// моли Христа Бога спастися душам нашим."},
  {"id": "cu-mol-0183", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0184", "section": "service", "who": "rubric", "text": "Макарию, митр. Киевскому,"},
  {"id": "cu-mol-0185", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0186", "section": "service", "who": "reader", "text": "Божественныя Безкровныя совершая Жертвы,/ кровь твою, от безбожных агарян излиянную,/ в жертву непорочную принесл еси Владыце твоему, Пастыреначальнику Христу./ Егоже моли, молим тя,/ пролити гнев на языки, хотящия браней;/ христолюбивое воинство наше на враги укрепи/ и стадо твое от всяких бед неврежденно соблюди,/ тебе бо крепкаго заступника почитаем,/ новый священномучениче российский,// святителю блаженный Макарие."},
  {"id": "cu-mol-0187", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0188", "section": "service", "who": "rubric", "text": "Мефодию, еп. Патарскому,"},
  {"id": "cu-mol-0189", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0190", "section": "service", "who": "reader", "text": "Кровь твоя, мудре, тайно вопиет от земли,/ якоже Авелева к Богу,/ Богомудре святителю Мефодие,/ ясно проповедавый Божие вочеловечение./ Темже и посрамил еси Оригенову лесть,/ и преставился еси в Небесный чертог./ Моли Христа Бога,// да спасет души наша."},
  {"id": "cu-mol-0191", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0192", "section": "service", "who": "rubric", "text": "Никите Славянину,"},
  {"id": "cu-mol-0193", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0194", "section": "service", "who": "reader", "text": "Постнически подвизався и плоть покорив духу, вшел еси в тишину безстрастия, иерейством же украшен, за Христа пострадал еси твердейши, Емуже молися о чтущих тя, священномучениче Никито приснопамятне."},
  {"id": "cu-mol-0195", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0196", "section": "service", "who": "rubric", "text": "Панкратию, еп. Тавроменийскому,"},
  {"id": "cu-mol-0197", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0198", "section": "service", "who": "reader", "text": "Яко стрела огнезрачная,/ от Верховнаго послан был еси Тавроменийскому престолу/ уязвляти безбожных злочестие,/ верных же сердца просвещати,/ яже боговещанными твоими словесы в вере утвердив/ и течение совершив, пострадал еси до крове,/ священномучениче Панкратие,// моли за вся, поющия память твою."},
  {"id": "cu-mol-0199", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0200", "section": "service", "who": "rubric", "text": "Петру, архиеп. Александрийскому,"},
  {"id": "cu-mol-0201", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0202", "section": "service", "who": "reader", "text": "От вышняго суда Христова предстательствова стаду,/ на пажитех благожизненных упасл еси всемудрыми твоими догматы,/ отгнав Ария, яко волка некроткаго,/ вшедшаго в них безбожными учении./ Темже и душу твою положил еси за них,/ пастырь нареклся еси, яко рече Господь,/ иерарше Петре блаженне,/ моли Христа Бога грехов оставление даровати// чтущим любовию святую память твою."},
  {"id": "cu-mol-0203", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0204", "section": "service", "who": "rubric", "text": "Петру (Полянскому), митр. Крутицкому,"},
  {"id": "cu-mol-0205", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "cu-mol-0206", "section": "service", "who": "reader", "text": "Божиим смотрением к святительскому служению/ святым Патриархом Тихоном призванный,/ стаду Христову явился еси страж неусыпный/ и защитник небоязненный,/ священномучениче Петре./ Жестокая заточения и дальная изгнания,/ страдания и смерть от богоборцев претерпел еси./ Венец мученический прияв,/ на Небеси ныне радуешися./ Моли милостиваго Бога,/ да сохранит Церковь нашу от нестроений,/ единомыслие и мир людем Своим дарует// и спасет души наша."},
  {"id": "cu-mol-0207", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0208", "section": "service", "who": "rubric", "text": "Серафиму (Чичагову), митр. Петроградскому,"},
  {"id": "cu-mol-0209", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "cu-mol-0210", "section": "service", "who": "reader", "text": "Воинство Царя Небеснаго/ паче земнаго возлюбив,/ служитель пламенный Святыя Троицы явился еси./ Наставления Кронштадтскаго пастыря/ в сердце своем слагая,/ данная ти от Бога многообразная дарования/ к пользе народа Божия преумножил еси./ Учитель благочестия/ и поборник единства Церковнаго быв,/ пострадати даже до крове сподобился еси./ Священномучениче Серафиме,/ моли Христа Бога// спастися душам нашим."},
  {"id": "cu-mol-0211", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0212", "section": "service", "who": "rubric", "text": "Фаддею (Успенскому), архиеп. Тверскому,"},
  {"id": "cu-mol-0213", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0214", "section": "service", "who": "reader", "text": "Хвала Богу и жертва живая/ житие твое, священномучениче Фаддее, явися./ Постом, бдением и молитвою Небесная дарования приим,/ многим добрый помощник и утешитель бысть./ Пастырскою мудростию и тихостию нрава украшен,/ лукавства врагов Христовых препобедил еси./ Слава Давшему тебе во страданиих крепость,/ слава, яко мученика, Венчавшему тя,// слава Действующему тобою всем исцеления."},
  {"id": "cu-mol-0215", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0216", "section": "service", "who": "rubric", "text": "Харалампию, епископу Магнезийскому,"},
  {"id": "cu-mol-0217", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0218", "section": "service", "who": "reader", "text": "Яко столп избранный Церкве Христовой/ и светильник присносветлый всея вселенныя,/ премудре показася, Харалампие,/ возсия в мире мучением,/ разруши идольское мракобесие, блаженне,/ сего ради явися предстатель Христу,// молися спастися нам."},
  {"id": "cu-mol-0219", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0220", "section": "service", "who": "rubric", "text": "^ Тропари преподобномученикам"},
  {"id": "cu-mol-0221", "section": "service", "who": "rubric", "text": "Адриану Пошехонскому, Ярославскому,"},
  {"id": "cu-mol-0222", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0223", "section": "service", "who": "reader", "text": "Христову мученику Адриану тезоименит был еси, преподобне,/ многия труды подъял еси в жизни временней,/ обитель иноческую созидая в пустыни,/ идеже пострадал еси даже до крове от злых разбойник/ и мученическую смерть от них приял еси,/ Адриане славне,/ чудес благодатию обогатився,/ предстоиши всех Царю, Христу Богу,// Егоже моли спастися душам нашим."},
  {"id": "cu-mol-0224", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0225", "section": "service", "who": "rubric", "text": "Александру (Пересвету) и Андрею (Ослябе), Радонежским,"},
  {"id": "cu-mol-0226", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0227", "section": "service", "who": "reader", "text": "Воини Христолюбивии, страдальцы послушания прехвальнии,/ Александре дивный Пересвете и Андрее Ослябей именуемый,/ Сергия игумена благодатные наследницы,/ Куликовския брани ратницы духовнии,/ вы бо змия агарянскаго победисте./ Но и нас своим заступлением не остависте,/ телами в храме Рождества Богородицы почиваете,/ душею в превышнем селении пребываете./ Молите за весь род русский православный,// преподобнии сродницы наши."},
  {"id": "cu-mol-0228", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0229", "section": "service", "who": "rubric", "text": "Анастасию, диакону Печерскому, в Ближних пещерах,"},
  {"id": "cu-mol-0230", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0231", "section": "service", "who": "reader", "text": "Плотское, яко безплотный Ангел, возненавидевши препитание,/ духовную во иноческом чину возлюбил еси пищу,/и в нем Боговидцу на Синаи Моисею/ добрым жития твоего подвигом уподобляяйся,/ многими на горе Божией Печерской возвысился еси добродетельми,/ идеже в молении к Вышнему непрестанно пребывал еси,/ ныне же со отцы преподобными Печерскими,/ аки бисер многоценен, мощми нетленными/ в пещере твоими пресветло сияеши,/ а душею со Ангелы пред Престолом Божиим,/ святый преподобномучениче Анастасие, предстоиши,/ о нас всегда моляся ко Господу// спастися душам нашим."},
  {"id": "cu-mol-0232", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0233", "section": "service", "who": "rubric", "text": "Андрею Критскому,"},
  {"id": "cu-mol-0234", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0235", "section": "service", "who": "reader", "text": "Постнически преподвизався на горе,/ умная врагов ополчения всеоружием Креста погубил еси, всеблаженне./ Паки же ко страдальчеству/ мужески облеклся еси,/ убив Копронима мечем веры;/ и обоих ради венчался еси от Бога,// преподобномучениче Андрее, приснопамятне."},
  {"id": "cu-mol-0236", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0237", "section": "service", "who": "rubric", "text": "Афанасию Брестскому,"},
  {"id": "cu-mol-0238", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "cu-mol-0239", "section": "service", "who": "reader", "text": "Блажен еси, отче наш Афанасие,/ яко верно пожил еси, стоя бодренно за святую Православную веру,/ со умилением присно поя неседальное Пречистей,/ заповедуя никомуже нарушати Православныя веры святыя,/ пострадав за свидетельство истины даже до смерти./ Мы же чтуще святыню твою,/ со дерзновением взываем ти:/ отче наш, преподобномучениче Афанасие,// похвало и украшение наше."},
  {"id": "cu-mol-0240", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0241", "section": "service", "who": "rubric", "text": "Дометию Персянину,"},
  {"id": "cu-mol-0242", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0243", "section": "service", "who": "reader", "text": "Постнически предподвизався на горе,/ умная врагов ополчения/ всеоружием Креста погубил еси, всеблаженне./ Паки же ко страдальчеству мужески облеклся еси,/ убив Копронима мечем веры,/ и обоих ради венчался еси от Бога,// преподобномучениче Дометие приснопамятне."},
  {"id": "cu-mol-0244", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0245", "section": "service", "who": "rubric", "text": "Евдокии Илиопольской,"},
  {"id": "cu-mol-0246", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0247", "section": "service", "who": "reader", "text": "Правостию умною душу твою привязавши в любовь Христову,/ тленных, и красных, и временных забытием претекла еси,/ яко Слова ученица:/ пощением страсти первее умертвивши,/ страдальчески второе врага посрамила еси./ Тем Христос сугубых венца сподоби тя,/ славная Евдокие, преподобная страстотерпице,// моли Христа Бога спастися душам нашим."},
  {"id": "cu-mol-0248", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0249", "section": "service", "who": "rubric", "text": "Евстратию Печерскому, в Ближних пещерах,"},
  {"id": "cu-mol-0250", "section": "service", "who": "rubric", "text": "глас 7"},
  {"id": "cu-mol-0251", "section": "service", "who": "reader", "text": "Постником и мучеником явился еси похвала, преподобне Евстратие,/ прежде бо воздержанием плоть умертвив,/ последовал еси Христу, нося крест свой./ Последи же и сам на крест вознесен быв/ и копием в ребра прободен,/ в руце Божий душу предал еси./ Колесницею огненною возносим на Небеса,/ сугубо венчался еси от Христа Бога// и Спаса душ наших."},
  {"id": "cu-mol-0252", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0253", "section": "service", "who": "rubric", "text": "Евфимию Новому, Афонскому, Константинопольскому,"},
  {"id": "cu-mol-0254", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0255", "section": "service", "who": "reader", "text": "Постнически преподвизався на горе,/ умная врагов ополчения всеоружием Креста погубил еси, всеблаженне./ Паки же ко страдальчеству/ мужески облеклся еси,/ убив Копронима мечем веры;/ и обоих ради венчался еси от Бога,// преподобномучениче Евфимие, приснопамятне."},
  {"id": "cu-mol-0256", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0257", "section": "service", "who": "rubric", "text": "Евфимию, Игнатию и Акакию Афонским,"},
  {"id": "cu-mol-0258", "section": "service", "who": "rubric", "text": "глас 7"},
  {"id": "cu-mol-0259", "section": "service", "who": "reader", "text": "Равночислении Троицы Несозданныя суще,/ с лики Ангелов и чины мучеников/ предстоите вы, радующеся, Престолу Божества, мудрии./ Сего ради причастием сияние отонуду приемлюще,/ источник исцелений верным подаете/ и Божественное просвещение,/ мучениче Христов Евфимие со Игнатием мудрым и с Божественным Акакием,// о нас присно молитеся."},
  {"id": "cu-mol-0260", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0261", "section": "service", "who": "rubric", "text": "Евфросину Синозерскому, Новгородскому,"},
  {"id": "cu-mol-0262", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0263", "section": "service", "who": "reader", "text": "От юности твоея вперив ум твой к Богу,/ блаженне Евфросине,/ мира же отвергся,/ вселился еси в пустыню непроходимую,/ и тамо, от Господа укрепляемь,/ в молитвах и пощениих доблественне пожил еси,/ и жизнь твою страдальчески/ убиением от сынов противления скончал еси,/ сего ради со преподобными и мученики венчался еси,/ с нимиже и ныне предстоиши Престолу Пресвятыя Троицы./ Сию моли, молим тя,/ оставление подати согрешений наших// и даровати нам велию милость."},
  {"id": "cu-mol-0264", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0265", "section": "service", "who": "rubric", "text": "Елисавете Феодоровне, вел. кн.,"},
  {"id": "cu-mol-0266", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0267", "section": "service", "who": "reader", "text": "Смирением достоинство княжеское сокрывши,/ богомудрая Елисавето,/ сугубым служением Марфы и Марии/ Христа почтила еси./ Милосердием, терпением и любовию себе предочистивши,/ яко жертва праведная Богу принеслася еси./ Мы же, чтуще добродетельное житие и страдания твоя,/ яко истинную наставницу усердно просим тя:/ святая мученице великая княгине Елисавето,// моли Христа Бога спасти и просветити души наша."},
  {"id": "cu-mol-0268", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0269", "section": "service", "who": "rubric", "text": "Иосифу, Сергию, Антонию, Варлааму, Иову и Петру Раифским,"},
  {"id": "cu-mol-0270", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0271", "section": "service", "who": "reader", "text": "Православия неложнии ревнители и зловредных ересей обличители,/ пустыни Раифския новомученицы святии,/ пред богоборцы Христа исповедали есте./ Пред Престолом Божиим с преподобными отцами ныне предстоя,/ молите Христа Бога спастися душам нашим."},
  {"id": "cu-mol-0272", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0273", "section": "service", "who": "rubric", "text": "Корнилию Псково-Печерскому,"},
  {"id": "cu-mol-0274", "section": "service", "who": "rubric", "text": "глас 6"},
  {"id": "cu-mol-0275", "section": "service", "who": "reader", "text": "Псково-Печерская обитель,/ издревле славная чудесы иконы Богоматерни,/ многия иноки Богови воспита,/ тамо и преподобный Корнилий/ подвигом добрым подвизася,/ чудную Богоматерь славя,/ иноверныя просвещая,/ иноки и многия люди спасая,/ обитель же свою дивно украшая и ограждая./ Тамо и мученичества венец/ по многих летех пастырства своего доблестне прият./ Темже воспоим, людие,/ Христа Бога и Пречистую Его Матерь возблагодарим,/ яко дарова нам преподобномученика славна// и молитвенника о душах наших достоблаженна."},
  {"id": "cu-mol-0276", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0277", "section": "service", "who": "rubric", "text": "Макарию Каневскому, архим. Овручскому, Переяславскому чдтв.,"},
  {"id": "cu-mol-0278", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0279", "section": "service", "who": "reader", "text": "Христу, нас ради с Небес сошедшему,/ последовал еси в подвизех твоих,/ Макарие, отче наш./ Егоже моли о нас, ублажающих тя,/ прощение прегрешений даровати нам,/ любовию же и смирением сердца наша озарити// и спасти души наша."},
  {"id": "cu-mol-0280", "section": "service", "who": "rubric", "text": "Ин тропарь, на перенесение мощей,"},
  {"id": "cu-mol-0281", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0282", "section": "service", "who": "reader", "text": "Ко всечестней раце многоцелебных мощей твоих,/ преподобномучениче Макарие,/ мы, грешнии, притекающе, дар исцеления приемлем:/ ты бо присно источаеши болящим здравие, печальным утешение/ и всех, чтущих тя, всякое исполняеши требование,// молящеся Христу Богу спастися душам нашим."},
  {"id": "cu-mol-0283", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0284", "section": "service", "who": "rubric", "text": "Параскеве Римской,"},
  {"id": "cu-mol-0285", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0286", "section": "service", "who": "reader", "text": "Тщание имущи сообразно имени твоему, тезоименитая,/ равноимянную тебе веру в сожительство избрала еси,/ Параскево победоносная,// темже изливаеши исцеления и молишися о душах наших."},
  {"id": "cu-mol-0287", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0288", "section": "service", "who": "rubric", "text": "Стефану Новому, исп.,"},
  {"id": "cu-mol-0289", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0290", "section": "service", "who": "reader", "text": "Постнически предподвизався на горе,/ умная врагов ополчения/ всеоружием Креста погубил еси, всеблаженне,/ паки же ко страдальчеству мужески вооружился еси,/ убив Копронима мечем веры,/ и обоих ради венчался еси от Бога,// преподобномучениче Стефане приснопамятне."},
  {"id": "cu-mol-0291", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0292", "section": "service", "who": "rubric", "text": "Феодору и Василию Печерским, в Ближних пещерах,"},
  {"id": "cu-mol-0293", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0294", "section": "service", "who": "reader", "text": "Союзом любве связавшеся, преподобнии,/ всяк союз козней вражиих попрасте,/ страдание же и смерть неповинне/ от сребролюбиваго князя претерпесте добле,/ тем молим вас, вкупе поживших/ и венцы мучения приемших,/ молитеся Господеви о нас,/ яко да во мнозей любви, вере и надежди добре поживше,/ всегда ублажаем вас,// Феодоре и Василие добропобеднии."},
  {"id": "cu-mol-0295", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0296", "section": "service", "who": "rubric", "text": "26-ти преподобномученикам Зографским,"},
  {"id": "cu-mol-0297", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0298", "section": "service", "who": "reader", "text": "Тревеличайшия светильники,/ всех преподобномученик Богоизбранный полк,/ двадесять и шесть Божественныя обители Зографския отец, почтим,/ прелесть латинскую обличившия/ и насильственно во огни скончавшияся;/ Фому пастыреначальника, священнаго Варсонофия,/ достославнаго Парфения и прочия, подвизавшияся,/ сошедшеся, песньми почтим,/ сии бо Троицу Святую// присно о нас умоляют."},
  {"id": "cu-mol-0299", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0300", "section": "service", "who": "rubric", "text": "^ Тропари мученикам"},
  {"id": "cu-mol-0301", "section": "service", "who": "rubric", "text": "Авкту и Тавриону,"},
  {"id": "cu-mol-0302", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0303", "section": "service", "who": "reader", "text": "Таврион славный и Авкт дивный,/ огневи противистася и всем инем казнем,/ молитвами возмогающа;/ та убо молением сердца похваляюще,/ верою пресвятую и честную память ею совершим,// душам просвещение почерпающа."},
  {"id": "cu-mol-0304", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0305", "section": "service", "who": "rubric", "text": "Авраамию Болгарскому, Владимирскому чдтв.,"},
  {"id": "cu-mol-0306", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0307", "section": "service", "who": "reader", "text": "Днесь, благовернии людие, сошедшеся,/ восхвалим добляго сего мученика и страдальца Авраамия,/ сей бо, укрепляемь силою Божиею,/ душу свою положи за Христа,/ много пострадав от зловерных болгар./ Сего ради от Господа венец прият/ и ныне предстоит Ему/ и молится о граде сем// и о всех нас, чтущих память его."},
  {"id": "cu-mol-0308", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0309", "section": "service", "who": "rubric", "text": "Адриану Никомидийскому,"},
  {"id": "cu-mol-0310", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0311", "section": "service", "who": "reader", "text": "Богатство неиждивущее вменил еси/ веру спасенную, треблаженне,/ оставль отеческое нечестие/ и Владыки стопами шествуя,/ Божественными даровании обогатился еси,/ Адриане славне;/ Христа Бога моли// спастися душам нашим."},
  {"id": "cu-mol-0312", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0313", "section": "service", "who": "rubric", "text": "Адриану и Наталии,"},
  {"id": "cu-mol-0314", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0315", "section": "service", "who": "reader", "text": "Мученицы Твои, Господи,/ во страданиих своих венцы прияша нетленныя от Тебе, Бога нашего:/ имуще бо крепость Твою,/ мучителей низложиша,/ сокрушиша и демонов немощныя дерзости./ Тех молитвами// спаси души наша."},
  {"id": "cu-mol-0316", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0317", "section": "service", "who": "rubric", "text": "Акиндину, Пигасию, Аффонию, Елпидифору, Анемподисту и иже с ними,"},
  {"id": "cu-mol-0318", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "cu-mol-0319", "section": "service", "who": "reader", "text": "Страстотерпцы Господни,/ блаженна земля, напившаяся кровьми вашими,/ и свята селения,/ приимшая телеса ваша:/ в тризнищи бо врага победисте/ и Христа со дерзновением проповедасте:/ Того яко блага молите// спастися, молимся, душам нашим."},
  {"id": "cu-mol-0320", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0321", "section": "service", "who": "rubric", "text": "Александре, царице Римской,"},
  {"id": "cu-mol-0322", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0323", "section": "service", "who": "reader", "text": "Царства земнаго славу презревши,/ Единаго Христа, нас ради распятаго, возлюбила еси/ и, Того мужественне исповедающи,/ венцем мученическим увенчалася еси,/ всеблаженная царице Александро./ Темже и ныне Престолу Царя славы на Небесех предстоящи,// молися о спасении душ наших."},
  {"id": "cu-mol-0324", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0325", "section": "service", "who": "rubric", "text": "Ангели, новомч.,"},
  {"id": "cu-mol-0326", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0327", "section": "service", "who": "reader", "text": "Лик ангельский, Ангели новомучениче,/ и сонмы страстотерпец восплескаша выспрь/ твоему веры ради терпению и прекословию/ и дух твой по благомудрию возведоша на Небеса// со славою ко Христу Богу нашему."},
  {"id": "cu-mol-0328", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0329", "section": "service", "who": "rubric", "text": "Андрею Стратилату,"},
  {"id": "cu-mol-0330", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "cu-mol-0331", "section": "service", "who": "reader", "text": "Земнаго сана славу оставив,/ Небесное Царство наследовал еси,/ кровными каплями, яко пречудным камением,/ нетленныя венцы украсил еси/ и ко Христу привел еси собор страстотерпец./ С лики ангельскими в невечернем свете/ незаходимаго Солнца Христа обрел еси,/ святе Андрее Стратилате,/ Егоже моли с пострадавшими с тобою присно,// да спасет души наша."},
  {"id": "cu-mol-0332", "section": "service", "who": "rubric", "text": "Кондак, глас 2"},
  {"id": "cu-mol-0333", "section": "service", "who": "reader", "text": "В молитвах Господеви предстоя,/ якоже звезда солнцу предтекий,/ и желаемое сокровище Царствия узрел еси,/ радости неизреченныя исполняяся./ Безсмертному Царю в бесконечныя веки,/ от Ангел безпрестани хвалимому, поеши, Андрее Стратилате.// С нимиже молися непрестанно о всех нас."},
  {"id": "cu-mol-0334", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0335", "section": "service", "who": "rubric", "text": "Антонию, Иоанну и Евстафию Литовским,"},
  {"id": "cu-mol-0336", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0337", "section": "service", "who": "reader", "text": "Иже земных чести и славы отвергшеся,/ доблии и честнии страдальцы,/ веры ради крепко и мужественно муки претерпесте,/ на смерть себе вдавше за Живот всех – Владыку./ Темже и Христос преславно столпом облачным/ с Небесе вас озари/ и почестьми и венцы от Престола славы венча./ Со Ангелы Тому предстояще,// молите спастися душам нашим."},
  {"id": "cu-mol-0338", "section": "service", "who": "rubric", "text": "Ин тропарь, глас тойже"},
  {"id": "cu-mol-0339", "section": "service", "who": "reader", "text": "От корене неплодна, преблаженнии,/ возрастивше Православныя веры ветви,/ первомучеником тезоименитии явистеся:/ злаго бо и нечестиваго князя ярости не убоястеся,/ повелевающа Христа отрещися./ Сего ради мученическия венцы приемше/ и со Ангелы Престолу Владычню предстояще,/ о нас молитеся, преблаженнии,// православно чтущих святую память вашу."},
  {"id": "cu-mol-0340", "section": "service", "who": "rubric", "text": "Кондак, глас 3"},
  {"id": "cu-mol-0341", "section": "service", "who": "reader", "text": "Отеческую прелесть оставльше, святии,/ приведостеся Христови,/ всем души усердием стасте мужемудренно до смерти./ Темже и взясте победы почесть воистинну,// о всех Владыку нашего непрестанно моляще."},
  {"id": "cu-mol-0342", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0343", "section": "service", "who": "rubric", "text": "Арефе и с ним 4299-ти,"},
  {"id": "cu-mol-0344", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0345", "section": "service", "who": "reader", "text": "Мужествовавше во Христе противу безбожнаго царя,/ мученицы святии,/ и того неверие иудейское во Христа обличивше,/ прияша мук томление и главам усечение;/ тем восхвалиша тя Ангели,/ и верных роди тя прославляют, Арефо,/ и пострадавших с тобою,// яко молящихся присно о душах наших."},
  {"id": "cu-mol-0346", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0347", "section": "service", "who": "rubric", "text": "Бояну, кн. Болгарскому,"},
  {"id": "cu-mol-0348", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0349", "section": "service", "who": "reader", "text": "Якоже Авель, от суда братняго смерть приял еси/ и кровь твою пролиял еси за Искупившаго ны честною Своею Кровию./ От земнаго же к Небесному преставився Царствию,/ княже и мучениче Енравоте-Бояне,// моли Царя царей о нас, присных твоих."},
  {"id": "cu-mol-0350", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0351", "section": "service", "who": "rubric", "text": "Вере, Надежде, Любови и матери их Софии,"},
  {"id": "cu-mol-0352", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0353", "section": "service", "who": "reader", "text": "Торжествует Церковь первородных,/ и свеселится приемля матерь о чадех веселящуюся,/ яже яко мудрости тезоименитая/ тройственным богословским добродетелем равночисленныя породи./ Тыя с мудрыми девами зрит уневестившияся Жениху Богу Слову,/ с нею и мы духовне в памяти их свеселимся, глаголюще:/ Троицы поборницы,/ Веро, Любве и Надеждо,// в вере, любви и надежде утверждайте нас."},
  {"id": "cu-mol-0354", "section": "service", "who": "rubric", "text": "Кондак, глас 1"},
  {"id": "cu-mol-0355", "section": "service", "who": "reader", "text": "Софии честныя священнейшия ветви,/ Вера и Надежда и Любовь, показавшеся,/ мудрость обуиша еллинскую благодатию,/ и пострадавше, и победоносицы явившеся,// венцем нетленным от всех Владыки Христа увязошася."},
  {"id": "cu-mol-0356", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0357", "section": "service", "who": "rubric", "text": "Вонифатию Тарсийскому,"},
  {"id": "cu-mol-0358", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0359", "section": "service", "who": "rubric", "text": "К сословию послан мучеников,/ мученик был еси истинен,/ пострадав за Христа крепчайше, всехвальне,/ мощми же возвратился еси верою пославшей тя, Вонифатие блаженне,// моли Христа Бога прияти нам грехов прощение."},
  {"id": "cu-mol-0360", "section": "service", "who": "rubric", "text": "Кондак, глас 4"},
  {"id": "cu-mol-0361", "section": "service", "who": "reader", "text": "Священие непорочное/ самовольне Тебе привел еси,/ иже от Девы тебе ради родитися Хотящему,/ святе венченосче,// премудре Вонифатие."},
  {"id": "cu-mol-0362", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0363", "section": "service", "who": "rubric", "text": "Гавриилу Белостокскому, младенцу,"},
  {"id": "cu-mol-0364", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "cu-mol-0365", "section": "service", "who": "reader", "text": "Святый младенче Гаврииле,/ ты за Прободеннаго нас ради от иудей/ люте от онехже в ребра прободен был еси/ и за Истощившаго кровь Свою за нас/ все тело твое на истощение крове/ в лютыя язвы предал еси,/ ныне же во славе вечней с Ним вселился еси./ Тем помяни и нас, молим, зде чтущих память твою,/ прося нам здравие телеси// и спасение душам нашим."},
  {"id": "cu-mol-0366", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0367", "section": "service", "who": "rubric", "text": "Георгию Новому, Софийскому,"},
  {"id": "cu-mol-0368", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0369", "section": "service", "who": "reader", "text": "Божественным желанием от юнаго возраста/ весь сам себе Господеви возложив,/ в молитвах и постех образ быв добродетели,/ богатство же, и славу, и доброродство телесное, яко не сущее, презрев,/ и Христа единаго от души возлюбил еси,/ и Того, истиннаго суща Бога, в Троице покланяема,/ пред нечестивыми турки проповедал еси,/ и, срацынскую веру, и законы Моамефовы под ногами поправ/ и мучителя ужасив,/ мучения венцем украсився, славне,/ к Небесным востекл еси ликостоянием,/ премудре Георгие./ Моли Христа Бога/ сохранити отечество твое и спасти люди и град,// иже твоя подвиги присно почитающия."},
  {"id": "cu-mol-0370", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0371", "section": "service", "who": "rubric", "text": "Гурию, Самону и Авиву, испп.,"},
  {"id": "cu-mol-0372", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "cu-mol-0373", "section": "service", "who": "reader", "text": "Чудеса святых Твоих мученик/ стену необоримую нам даровавый, Христе Боже,/ тех молитвами советы языков разори,/ Церковь святую укрепи,// яко Един Благ и Человеколюбец."},
  {"id": "cu-mol-0374", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0375", "section": "service", "who": "rubric", "text": "Девяти мученикам Кизическим,"},
  {"id": "cu-mol-0376", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0377", "section": "service", "who": "reader", "text": "Святии девяточисленнии мученицы,/ от различных градов во един лик совокупившеся манием Божественным,/ мужественно за Христа пострадасте,/ невидимаго врага победисте,/ зловерныя князи и мучители посрамисте вашим терпением,/ огнем же любве Божия разжизаеми,/ вещественно вас огнь мучащий в хлад преложисте,/ темже дадеся вам от Христа Бога благодать/ трясавичную исцеляти болезнь,/ от неяже и многовидных страстей,// милостивно спасайте и нас предстательством вашим, молимся."},
  {"id": "cu-mol-0378", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0379", "section": "service", "who": "rubric", "text": "Диомиду, врачу,"},
  {"id": "cu-mol-0380", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0381", "section": "service", "who": "reader", "text": "Мучительнии сосуди устроиша ти путь к Небесем,/ Христов воине Диомиде,/ победив диавольския козни,/ и на Небесех у Христа прославися,// молися за творящих верою память твою."},
  {"id": "cu-mol-0382", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0383", "section": "service", "who": "rubric", "text": "Евстратию, Авксентию, Евгению, Мардарию и Оресту,"},
  {"id": "cu-mol-0384", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0385", "section": "service", "who": "reader", "text": "Мученик всечестных светлость,/ пяточисленных страстотерпцев воспоем,/ славу земных презревших,/ солнца светлаго Евстратия,/ премудраго витию со страдальцы,/ на огнь и муки дерзнувших за всех Царя Христа/ и от престола Того славы почестьми венцев обдаренных./ Тех молитвами, Христе Боже,// спаси души наша."},
  {"id": "cu-mol-0386", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0387", "section": "service", "who": "rubric", "text": "Иоанну-Владимиру, кн. Сербскому,"},
  {"id": "cu-mol-0388", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0389", "section": "service", "who": "reader", "text": "Крест, явльшийся тебе с Небесе, светел проповедал еси,/ просветив языки ясно, Владимире славне,/ обагреньми кровей твоих украсився,/ сподобился еси почестей нетленных,/ предстояй Троице,/ тем со дерзновением// моли спастися нам."},
  {"id": "cu-mol-0390", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0391", "section": "service", "who": "rubric", "text": "Иоанну Воину,"},
  {"id": "cu-mol-0392", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0393", "section": "service", "who": "reader", "text": "Всеблагаго Бога и Царя/ благоверный раб и воин явился еси, Иоанне чудодетелю,/ пострадав бо ради веры мужески,/ блаженно же скончав течение,/ зриши Всетворца Господа в Небесех светлейше./ От Негоже прием дарование чудес,/ страждущим человеком во всяких напастех помогаеши,/ укрепляеши воины в ратех,/ от врагов пленения, ран же и внезапных смертей и от бед лютых изымаеши./ Темже моли Владыку Христа, приснопамятне,/ да во всяком обстоянии сотворит нам милость,/ и не введет нас во искушения,// но спасет души наша, яко Человеколюбец."},
  {"id": "cu-mol-0394", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0395", "section": "service", "who": "rubric", "text": "Иоанну Казанскому, мч.,"},
  {"id": "cu-mol-0396", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "cu-mol-0397", "section": "service", "who": "reader", "text": "Страстотерпче святый Иоанне,/ блаженна земля, напившаяся крове твоея,/ Христа бо со дерзновением проповедав,/ многия муки от неверных агарян приял еси,/ страданьми своими противных дерзости низложив,/ Троицы поборник явился еси,// Юже и моли даровати нам велию милость."},
  {"id": "cu-mol-0398", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0399", "section": "service", "who": "rubric", "text": "Иоанну, бывшему Моавию, царю Персидскому, и иже с ним трем отрокам,"},
  {"id": "cu-mol-0400", "section": "service", "who": "rubric", "text": "глас 6"},
  {"id": "cu-mol-0401", "section": "service", "who": "reader", "text": "Иже ко Христу верою/ болезнь телесную исцели, с неюже и душевную,/ наставляемь от честнаго твоего учителя Феодора,/ славный царю Моавие Иоанне,/ и, страдание по Христе купно с верными твоими треми отроки скончав,/ явися в царех мученик, в мученицех же царь,/ по Христе течение скончав, от своих раб волею пострада,/ и, сугубу честь от Бога приим,/ Егоже моли купно с треми верными твоими отроки// спастися душам нашим."},
  {"id": "cu-mol-0402", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0403", "section": "service", "who": "rubric", "text": "Иоанну, Стефану, Петру, Борису, Иакову, Феодору, Сильвану, Феодору, Василию, Феодору, Димитрию, Михаилу, Иоанну и Василию Казанским,"},
  {"id": "cu-mol-0404", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0405", "section": "service", "who": "reader", "text": "Молитвами Твоих мучеников, Господи,/ благочестие в стране Казанстей насадися,/ и, яко пламенем огненным./ Православной верой Восток озарися,/ и ныне их предстательством, Человеколюбче,/ не помяни беззаконий наших,/ но утверди нас в вере истинней// и мир подаждь, молимся Ти."},
  {"id": "cu-mol-0406", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0407", "section": "service", "who": "rubric", "text": "Иулиану Египетскому и иже с ним,"},
  {"id": "cu-mol-0408", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0409", "section": "service", "who": "reader", "text": "Светлыя постничества подвиги,/ радуяся, понесл еси, Иулиане Богоблаженне, с преподобною Василиссою,/ и страдания добльственно претерпел еси/ с честными твоими сострадальцы,/ с нимиже моли Христа Бога// спастися душам нашим."},
  {"id": "cu-mol-0410", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0411", "section": "service", "who": "rubric", "text": "Киру и Иоанну, бессребреникам,"},
  {"id": "cu-mol-0412", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "cu-mol-0413", "section": "service", "who": "reader", "text": "Премудрии вселенней врачеве,/ Кире и Иоанне,/ от Бога приясте власть целити недуги душевныя,/ вкупе же и телесныя,/ и ныне молитеся/ сохранити град и люди от одержащих зол// и спасти молитвами вашими души наша."},
  {"id": "cu-mol-0414", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0415", "section": "service", "who": "rubric", "text": "Кирику и Иулитте,"},
  {"id": "cu-mol-0416", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0417", "section": "service", "who": "reader", "text": "Яко лоза благоплодная, Иулитто честная,/ грозд зрел принесла еси Цареви, всех Богу,/ сына твоего Кирика славнаго,/ мучением того богатно украсивши/ и твоею кровию навершивши,/ тем и дарова тебе Вышний возмездие в Вышних,// идеже ликующе, помяните нас, мученицы терпеливодушнии."},
  {"id": "cu-mol-0418", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0419", "section": "service", "who": "rubric", "text": "Конону Исаврийскому,"},
  {"id": "cu-mol-0420", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0421", "section": "service", "who": "reader", "text": "Яко девственника предивна/ и мученика непоколебима,/ блаженнаго страдальца,/ на бесы власть приемшаго,/ Конона песньми восхвалим и к нему возопиим:/ моли Христа Бога,// да спасет души наша."},
  {"id": "cu-mol-0422", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0423", "section": "service", "who": "rubric", "text": "Людмиле, кн. Чешской,"},
  {"id": "cu-mol-0424", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0425", "section": "service", "who": "reader", "text": "Оставльша тьму идолослужения/ и с горячей любовию прияв свет Православныя веры Христовы,/ явися ты, святая Людмило, яко звезда утренняя,/ и светом святости твоея// истинный день Богопочитания в Честей земли начав."},
  {"id": "cu-mol-0426", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0427", "section": "service", "who": "rubric", "text": "Маркиану и Мартирию,"},
  {"id": "cu-mol-0428", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0429", "section": "service", "who": "reader", "text": "Мученик двоица единонравная,/ Маркиан с Мартирием славным, Ариево нечестие разрушиша/ и Соприсносущна Сына Отцу и Духови веровати научиша,/ Павлу повинующеся истинных повелений учителю,/ темже мечем убиени, умроша;/ и присно со Христом живуще,/ о нас Того молят// спасти души наша."},
  {"id": "cu-mol-0430", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0431", "section": "service", "who": "rubric", "text": "Меркурию Смоленскому, воину,"},
  {"id": "cu-mol-0432", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "cu-mol-0433", "section": "service", "who": "reader", "text": "Возсияв, яко звезда многосветлая,/ в соборней церкви пред пречистым и чудотворным образом Пречистей Богородицы,/ за Нюже и за град Смоленск пострада,/ многокозненнаго и богомерзкаго царя Батыя устраши,/ и сильнаго исполина победи, и люди удиви,/ душу свою, многострадальне Меркурие, за благочестие положи,/ яко Захариина и Авелева ясно вопиет твоя кровь ко Господу.// И ныне молися за души наша."},
  {"id": "cu-mol-0434", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0435", "section": "service", "who": "rubric", "text": "Мине, Ермогену и Евграфу,"},
  {"id": "cu-mol-0436", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0437", "section": "service", "who": "reader", "text": "Воздержанием страстей огнепальныя/ умертвивше зраки и движения, Христовы мученицы,/ прияша благодать недуги отгоняти немощных,/ и живше и по кончине чудодействовати;/ воистину чудо преславно,/ яко кости наги источают исцеления,// слава Единому и Создателю Богу."},
  {"id": "cu-mol-0438", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0439", "section": "service", "who": "rubric", "text": "Миропии,"},
  {"id": "cu-mol-0440", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0441", "section": "service", "who": "reader", "text": "Добромученице Миропие и Христа невесто нетленная,/ ныне Емуже предстоиши, прекрасная,/ раны носящи плоти,/ яко камни светлы и светообразны,/ и в кровавую порфиру, яко царица, облеченная, преславная,/ умоли Его за ны,/ яже с любовию восхваляющия// хвалы победными и песньми твою Божественную страсть."},
  {"id": "cu-mol-0442", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0443", "section": "service", "who": "rubric", "text": "Михаилу Сновидцу,"},
  {"id": "cu-mol-0444", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "cu-mol-0445", "section": "service", "who": "reader", "text": "От добляго наставника Феодора/ чистоту твердо извыче,/ и от нечестия царицы Сеиды/ целомудрием по образу Иосифа сохранися,/ такоже и нечестиваго царя Адрамелеха/ премудрыми твоими глаголы прения и ласкания низложив,/ и по Христе мучения венцем увязеся,/ Богомудрый Михаиле,// Егоже моли спасти души наша."},
  {"id": "cu-mol-0446", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0447", "section": "service", "who": "rubric", "text": "Михаилу, кн. Черниговскому, и боярину его Феодору, чдтвв., мчч. и испп.,"},
  {"id": "cu-mol-0448", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0449", "section": "service", "who": "reader", "text": "Жизнь вашу мученически совершивше,/ исповедания венцы украсившеся, к Небесным востекосте,/ Михаиле премудре с доблим Феодором,/ молите Христа Бога/ сохранити отечество ваше/ град же и люди,// по велицей Его милости."},
  {"id": "cu-mol-0450", "section": "service", "who": "rubric", "text": "Ин тропарь, на перенесение мощей,"},
  {"id": "cu-mol-0451", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0452", "section": "service", "who": "reader", "text": "Троичнаго Божества осиянием просветився,/ страстотерпче великий княже Михаиле,/ с премудрым болярином ти Феодором,/ самозванна к подвигом устремистася,/ сквозе огнь не идоста,/ кусту же и идолом не поклонистася, но оплеваста/ и нечестиваго царя обличиста,/ Христа же Единаго от Троицы Бога Суща исповедаста./ И того ради кровей своих струями обагристася, славная./ Темже и венца от Него победная прияста,/ и нас свыше назираета,/ молим вас, святыя, молите Того,/ яко да вашими молитвами избавит нас от всяких обстоящих ны зол/ и подаст нам вся благая,// иже Един Сый прославляемый во святых Своих."},
  {"id": "cu-mol-0453", "section": "service", "who": "rubric", "text": "Величание"},
  {"id": "cu-mol-0454", "section": "service", "who": "reader", "text": "Величаем тя,/ благоверный княже Михаиле,/ и с болярином твоим Феодором,/ и чтим святую память вашу,/ иже за Христа кровь свою излиясте,/ и ныне молите за нас Христа Бога нашего."},
  {"id": "cu-mol-0455", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0456", "section": "service", "who": "rubric", "text": "Кириакии Никомидийской,"},
  {"id": "cu-mol-0457", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0458", "section": "service", "who": "reader", "text": "Одолением чудесным/ победила еси вражия силы до конца,/ Недело преславная,/ идоложрения бо тьму/ далече Креста честнаго светлостию прогнала еси./ Мученице всехвальная,/ Христу Богу молися// даровати нам велию милость."},
  {"id": "cu-mol-0459", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0460", "section": "service", "who": "rubric", "text": "Николаю II, Императору Российскому, св. блгв.,"},
  {"id": "cu-mol-0461", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "cu-mol-0462", "section": "service", "who": "reader", "text": "Царства земнаго лишение,/ узы и страдания многоразличныя/ кротко претерпел еси,/ свидетельствовав о Христе даже до смерти от богоборцев,/ страстотерпче великий Боговенчанный царю Николае,/ сего ради мученическим венцем на Небесех,/ венча тя с царицею и чады и слуги твоими Христос Бог,/ Егоже моли помиловати страну Российскую// и спасти души наша."},
  {"id": "cu-mol-0463", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0464", "section": "service", "who": "rubric", "text": "Оресту, врачу,"},
  {"id": "cu-mol-0465", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0466", "section": "service", "who": "reader", "text": "Удом усекновение терпел еси/ и огненную лютую муку, мучениче,/ подвигся, всеславне,/ венцем яве увязеся нетленным, преблаженне,/ Престолу же предстоиши Святыя Троицы,/ Юже помоли, да спасет ны,/ мучениче Оресте,// верою поющим тя."},
  {"id": "cu-mol-0467", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0468", "section": "service", "who": "rubric", "text": "Параскеве (Пятнице),"},
  {"id": "cu-mol-0469", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0470", "section": "service", "who": "reader", "text": "Премудрая и всехвальная Христова мученица Параскева,/ мужескую крепость приимши,/ женскую же немощь отвергши,/ диавола победи и мучителя посрами,/ вопиющи и глаголющи:/ приидите, тело мое мечем ссецыте и огнем сожгите,/ аз бо, радующися, иду ко Христу, Жениху моему./ Тоя молитвами, Христе Боже,// спаси души наша."},
  {"id": "cu-mol-0471", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0472", "section": "service", "who": "rubric", "text": "Петру и Стефану, Казанским,"},
  {"id": "cu-mol-0473", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0474", "section": "service", "who": "reader", "text": "Мучеников двоица единонравная,/ Стефане и Петре славнии,/ неверие соплеменников обличивше,/ Христу последовали есте,/ во Святую Троицу веровати всех научающе,/ Еяже ради великия страдания приемше,/ молитеся о нас ко Господу,/ да, избавившеся тьмы греховныя,/ Света явимся общницы невечерняго."},
  {"id": "cu-mol-0475", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0476", "section": "service", "who": "rubric", "text": "Прову, Тараху и Андронику,"},
  {"id": "cu-mol-0477", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "cu-mol-0478", "section": "service", "who": "reader", "text": "Святых мученик исправлением/ Небесныя силы преудивишася,/ яко в теле смертнем,/ безтелеснаго врага силою Креста,/ подвизавшеся добре, победиша невидимо./ И молятся Господу// помиловатися душам нашим."},
  {"id": "cu-mol-0479", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0480", "section": "service", "who": "rubric", "text": "Савве Стратилату и с ним 70-ти воинам,"},
  {"id": "cu-mol-0481", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "cu-mol-0482", "section": "service", "who": "reader", "text": "Земнаго сана пояс оставив и почести, страдальче,/ пред мучителем, льстивым царем,/ Христа Бога суща исповедал еси,/ и Того ради многа страдания подъял еси, славне./ Тем прекрасным победы венцем увязлся еси/ от Царя всех царствующаго,/ с Небесными вои светло преукрашен./ Предстоя Тому, Савво,// моли, да спасет души наша."},
  {"id": "cu-mol-0483", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0484", "section": "service", "who": "rubric", "text": "Серафиме деве. Римской,"},
  {"id": "cu-mol-0485", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0486", "section": "service", "who": "reader", "text": "Невесто Христова возлюбленная, Серафимо,/ наследнице Царствия Небеснаго,/ добре за Господа пострадавшая/ и кровию твоею обагренная/ и, аки царскою багряницею, украшенная,// поминай нас, совершающих святую память твою."},
  {"id": "cu-mol-0487", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0488", "section": "service", "who": "rubric", "text": "Сергию и Вакху,"},
  {"id": "cu-mol-0489", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "cu-mol-0490", "section": "service", "who": "reader", "text": "Удобрение Христовых страстотерпец,/ и очи Христовы Церкве,/ очи просветите душ наших,/ Сергие многострадальне и Вакше преславне:/ молитеся ко Господу,/ яко да убежим тьмы греховныя,/ и света явимся общницы невечерняго,// молитвами вашими, святии."},
  {"id": "cu-mol-0491", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0492", "section": "service", "who": "rubric", "text": "Сорока мученикам Севастийским,"},
  {"id": "cu-mol-0493", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0494", "section": "service", "who": "reader", "text": "Страстотерпцы Христовы четыредесяте,/ во граде Севастийстем мужественно пострадавшии,/ чрез огнь и воду прошедшии,/ в покой вечный вшедшии,/ молитеся о нас ко Господу/ да жизнь мирну сохранит// и души наша спасет, яко Человеколюбец."},
  {"id": "cu-mol-0495", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0496", "section": "service", "who": "rubric", "text": "Стефану Дечанскому, царю Сербскому,"},
  {"id": "cu-mol-0497", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0498", "section": "service", "who": "reader", "text": "В терпении добрострадальных подвиг твоих/ многообразныя раны претерпел еси,/ и по кончине своей/ венец от Бога с мученическими лики восприемлеши,/ и в земли кротких достойно водворяешися, блаженне,/ о нас Христа Бога моли// даровати душам нашим велию милость."},
  {"id": "cu-mol-0499", "section": "service", "who": "rubric", "text": "Ин тропарь, на перенесение мощей,"},
  {"id": "cu-mol-0500", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0501", "section": "service", "who": "reader", "text": "Царскую диадиму обагрил еси кровию твоею, Богомудре великомучениче,/ за скиптр крест в руку приим,/ явился еси победоносец/ и яко жертву непорочну принесл еси себе Богу./ От родителей твоих очию зеницы лишен был еси,/ и в заточении пребыл еси,/ и от своих удавлен еси./ И ныне, радуяся, предстоиши Святей Троице./ Тем празднуем днесь пренесение честных мощей твоих/ и обновление честнаго кивота,/ блаженне Стефане, молися о державе сродник твоих,/ благоугодней быти ей// и сыновом сербским спастися."},
  {"id": "cu-mol-0502", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0503", "section": "service", "who": "rubric", "text": "Трофиму, Савватию и Доримедонту,"},
  {"id": "cu-mol-0504", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0505", "section": "service", "who": "reader", "text": "В Троице хвалимый Бог троицу мученик прослави,/ Трофима и Савватия и Доримедонта:/ в Того бо веровавше, врага низложиша./ Тех молитвами, Христе Боже наш, помилуй нас."},
  {"id": "cu-mol-0506", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0507", "section": "service", "who": "rubric", "text": "Трофиму, Феофилу и с ними 13-ти мученикам,"},
  {"id": "cu-mol-0508", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0509", "section": "service", "who": "reader", "text": "Яко воини, мученицы непобедимии,/ течением невозбранным в судилище неверных внидосте/ и веры ради многия муки претерпесте,/ Христа исповедающе Единаго со дерзновением./ Того молите, Трофиме и Феофиле с прочими,/ яко да тяготу страстей отложше,// ваше ныне страдание поем, страстотерпцы непреоборимии."},
  {"id": "cu-mol-0510", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0511", "section": "service", "who": "rubric", "text": "Уару и с ним семи учителям христианским,"},
  {"id": "cu-mol-0512", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0513", "section": "service", "who": "reader", "text": "Воинством святых страстотерпец страждущих законне,/ зря онех, показал еси мужески крепость свою./ И устремився на страсть волею,/ и умрети вожделе за Христа,/ Иже приял еси почесть победы твоего страдания, Уаре,// моли спастися душам нашим."},
  {"id": "cu-mol-0514", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0515", "section": "service", "who": "rubric", "text": "Фекле, равноап., первомц.,"},
  {"id": "cu-mol-0516", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0517", "section": "service", "who": "reader", "text": "Словесем Павловым научившися, богоневестная Фекло,/ и верою утвердившися от Петра, богозванная,/ первомученица явилася еси и первострадальница в женах;/ возшла еси на пламень, яко на место благоцветущее,/ звери и юнцы устрашишася тебе, вооружися бо Крестом./ Тем моли, всехвальная, Христа Бога,// спастися душам нашим."},
  {"id": "cu-mol-0518", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0519", "section": "service", "who": "rubric", "text": "Феодору варягу и сыну его Иоанну первомчч. Российским,"},
  {"id": "cu-mol-0520", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "cu-mol-0521", "section": "service", "who": "reader", "text": "Страстотерпцы Господни,/ Феодоре со Иоанном отроком, славнии!/ Блаженна земля Русская, напившаяся кровьми вашими,/ и радуется отечество наше,/ в немже вы первии, идолы посрамивше,/ Христа со дерзновением исповедасте/ и за Него пострадасте./ Того, яко Блага, молите,/ до скончания века в стране нашей Церковь Православную непоколебиму утвердити// и всех русских людей во истинней вере и благочестии сохранити."},
  {"id": "cu-mol-0522", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0523", "section": "service", "who": "rubric", "text": "Феодосии Константинопольской,"},
  {"id": "cu-mol-0524", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0525", "section": "service", "who": "reader", "text": "Добродетель благоприятно, мученице, постигла еси,/ Христово приятелище бывши чистое,/ и Святаго Духа дом возлюблен;/ отнюдуже посрамила еси врага, борющаго род человеческий,/ добре страдавшая,/ и посекла еси Копронима, Феодосие, мечем веры,/ и к чертогу Небесному преставилася еси, радующися./ Тебе верою чтущим// присно проси велия милости."},
  {"id": "cu-mol-0526", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0527", "section": "service", "who": "rubric", "text": "Флору и Лавру,"},
  {"id": "cu-mol-0528", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0529", "section": "service", "who": "reader", "text": "Преудобренную и богомудрую двоицу пресветлую/ восхвалим, вернии, по достоянию,/ Флора преблаженнаго и Лавра всечестнаго,/ иже усердно Троицу несозданную ясно проповедасте всем,/ темже пострадавше до крове,/ и венцы пресветлыми увязостеся,// молитеся Христу Богу, да спасет души наша."},
  {"id": "cu-mol-0530", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0531", "section": "service", "who": "rubric", "text": "Христине Тирской,"},
  {"id": "cu-mol-0532", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0533", "section": "service", "who": "reader", "text": "Званием евангельски Христу уневестившися,/ Христино славная,/ славу мира сего и похоть бренную вменила еси ни во что же,/ о самом телеси небрегущи,/ муки претерпела еси доблественно,/ тем твое страдание хвалами почитаем,// мученице, Христу тезоименитая."},
  {"id": "cu-mol-0534", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0535", "section": "service", "who": "rubric", "text": "Христофору, Ликийскому,"},
  {"id": "cu-mol-0536", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0537", "section": "service", "who": "reader", "text": "Одеждами от кровей украшаяся,/ Господеви предстоиши, Царю сил, Христофоре приснопамятне,/ отонудуже со Безплотными и мученики поеши/ трисвятым и страшным сладкопением./ Темже молитвами твоими спасай стадо твое."},
  {"id": "cu-mol-0538", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0539", "section": "service", "who": "rubric", "text": "10-ти мученикам Критским,"},
  {"id": "cu-mol-0540", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0541", "section": "service", "who": "reader", "text": "Многочудный Крит почтим,/ процветший честныя цветы,/ Христовы бисеры,/ мучеников сорасленых,/ десять бо суть числом, блаженнии,/ иже весь идольский народ посрамиша,// темже и венцы прияша, добледушнии."},
  {"id": "cu-mol-0542", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0543", "section": "service", "who": "rubric", "text": "45-ти мученикам Никопольским (Армянским),"},
  {"id": "cu-mol-0544", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0545", "section": "service", "who": "reader", "text": "Единоумне душею связани бывше,/ четыредесять с пятьми страдальцы святии,/ на врага ополчистеся,/ победителие же явльшеся,/ приясте венцы от Христа Бога/ и вечное мучений ваших воздаяние,/ тыя и нам улучити молите,// благочестно песньми вас величающим."},
  {"id": "cu-mol-0546", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0547", "section": "service", "who": "rubric", "text": "14000-м мученикам младенцам, от Ирода в Вифлееме избиенным,"},
  {"id": "cu-mol-0548", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0549", "section": "service", "who": "reader", "text": "Болезньми святых, имиже о Тебе пострадаша,/ умолен буди, Господи,/ и вся наша болезни исцели,/ Человеколюбче, молимся."},
  {"id": "cu-mol-0550", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0551", "section": "service", "who": "rubric", "text": "20000-м мученикам Никомидийским,"},
  {"id": "cu-mol-0552", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "cu-mol-0553", "section": "service", "who": "reader", "text": "Страстотерпцы Господни,/ блаженна земля, напившаяся кровьми вашими,/ и свята селения, приимшая телеса ваша:/ в подвизе бо врага победисте/ и Христа со дерзновением проповедасте./ Того, яко блага, молите// спастися, молимся, душам нашим."},
];

